// TBSCertificate ::= SEQUENCE {
//   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
//   issuer, validity, subject, subjectPublicKeyInfo,
//   issuerUniqueID [1], subjectUniqueID [2], extensions [3] }
let t = tbs.content;
let (first, t2) = read_tlv(t)?;
let (mut version, t) = if first.tag == 0xA0 {
    let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
    if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
        return Err("invalid certificate version".to_string());
    }
    (ver.content[0], t2)
} else {
    // No explicit version: v1 certificate.
    (0u8, t)
};

let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
let t = t3;
let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
let (spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
check_spki(spki)?;
// issuerUniqueID [1] and subjectUniqueID [2] are optional BIT
// STRINGs; they must still each be complete TLVs. The extensions
// field [3] is validated in full below and may appear at most once.
let mut seen_extensions = false;
while !t.is_empty() {
    let (tlv, rest) = read_tlv(t)?;
    match tlv.tag {
        0xA3 => {
            if seen_extensions {
                return Err(
                    "duplicate extensions field in tbsCertificate".to_string()
                );
            }
            seen_extensions = true;
            if version != 2 {
                let label = if version == 0 {
                    "v1".to_string()
                } else {
                    format!("v{}", version + 1)
                };
                return Err(format!(
                    "extensions require certificate version v3, found {label}"
                ));
            }
            check_extensions(tlv)?;
        }
        0xA1 | 0xA2 => {
            if tlv.content.is_empty() || tlv.content[0] > 7 {
                return Err("invalid unique identifier BIT STRING".to_string());
            }
        }
        _ => {
            return Err(format!(
                "unexpected element (tag 0x{:02X}) in tbsCertificate",
                tlv.tag
            ));
        }
    }
    t = rest;
}

