#!/usr/bin/env python3
import subprocess

BIN = "/opt/gsb-production/workspaces/sl-chen/prod-15/B/task026/target/debug/chainview"
TMP = "/tmp/cvtest.der"

def L(n):
    if n < 0x80:
        return bytes([n])
    b = []
    while n:
        b.append(n & 0xFF); n >>= 8
    b.reverse()
    return bytes([0x80 | len(b)]) + bytes(b)

def tlv(tag, content): return bytes([tag]) + L(len(content)) + content
def seq(c): return tlv(0x30, c)
def integer(c): return tlv(0x02, c)
def oid(arcs):
    first = arcs[0]*40 + arcs[1]
    def arc(v):
        out = [v & 0x7F]; v >>= 7
        while v:
            out.append(0x80 | (v & 0x7F)); v >>= 7
        out.reverse()
        return bytes(out)
    c = arc(first)
    for a in arcs[2:]: c += arc(a)
    return tlv(0x06, c)
def boolean(b): return tlv(0x01, bytes([b]))
def octs(c): return tlv(0x04, c)
def bits(c): return tlv(0x03, c)
def null(): return tlv(0x05, b"")
def cn(s):
    return seq(tlv(0x31, seq(oid([2,5,4,3]) + tlv(0x0C, s.encode()))))
def alg(): return seq(oid([1,2,840,113549,1,1,11]) + null())
def vty(nb=b"260115093000Z", na=b"270115093000Z"):
    return seq(tlv(0x17, nb) + tlv(0x17, na))

SERIAL = integer(bytes.fromhex("0E8A4C2F9B17D603"))
SPKI = seq(alg() + bits(b"\x00\x01\x00"))

def tbs_of(version=None, extra=b"", val=None):
    p = b""
    if version is not None:
        p += tlv(0xA0, integer(bytes([version])))
    p += SERIAL + alg() + cn("Test CA")
    p += val if val is not None else vty()
    p += cn("example.com") + SPKI + extra
    return seq(p)

def cert_of(tb): return seq(tb + alg() + bits(b"\x00"))

def ext(arcs=(2,5,29,14), crit=None, value=b"\x30\x00"):
    c = oid(list(arcs))
    if crit is not None: c += boolean(crit)
    c += octs(value)
    return seq(c)

def field_of(exts, wrap_extra=b"", outer=0xA3, inner=0x30, raw_inner=None):
    innerb = raw_inner if raw_inner is not None else tlv(inner, b"".join(exts))
    return tlv(outer, innerb + wrap_extra)

def v3(exts, **kw): return cert_of(tbs_of(version=2, extra=field_of(exts, **kw)))
def v3field(field, version=2, val=None):
    return cert_of(tbs_of(version=version, extra=field, val=val))

results = []
def run(name, data, expect_ok):
    with open(TMP, "wb") as f: f.write(data)
    p = subprocess.run([BIN, "inspect", TMP], capture_output=True)
    if expect_ok:
        ok = p.returncode == 0 and p.stderr == b""
    else:
        ok = (p.returncode == 2 and p.stdout == b""
              and p.stderr.startswith(b"chainview: invalid DER certificate: ")
              and b"extension" in p.stderr.lower())
    results.append((name, ok, p.returncode, p.stdout, p.stderr))

# accepted
run("v3 one unknown oid empty value", v3([ext(arcs=(1,2,3,4), value=b"")]), True)
run("v3 critical FF", v3([ext(crit=0xFF)]), True)
run("v3 two extensions", v3([ext(arcs=(2,5,29,14)), ext(arcs=(2,5,29,15), crit=0xFF, value=b"\x01\x02\x03")]), True)
run("v1 implicit no ext", cert_of(tbs_of()), True)
run("v1 explicit no ext", cert_of(tbs_of(version=0)), True)
run("v2 explicit no ext", cert_of(tbs_of(version=1)), True)
run("expired cert with ext",
    cert_of(tbs_of(version=2, extra=field_of([ext()]),
                  val=vty(b"200101000000Z", b"010101000000Z"))), True)

# version constraints
run("implicit v1 with ext", v3field(field_of([ext()]), version=None) if False else
    cert_of(tbs_of(extra=field_of([ext()]))), False)
run("explicit v1 with ext", v3field(field_of([ext()]), version=0), False)
run("explicit v2 with ext", v3field(field_of([ext()]), version=1), False)
run("duplicate ext fields",
    cert_of(tbs_of(version=2, extra=field_of([ext()]) + field_of([ext()]))), False)

# wrapper
run("empty wrapper", cert_of(tbs_of(version=2, extra=tlv(0xA3, b""))), False)
run("empty extensions sequence", cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(b"")))), False)
run("wrapper extra element", v3([ext()], wrap_extra=integer(b"\x01")), False)
run("wrapper two sequences",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, tlv(0x30, ext()) + seq(b"")))), False)
run("wrapper non-sequence", cert_of(tbs_of(version=2, extra=tlv(0xA3, integer(b"\x01")))), False)

# extension item structure
run("ext item not sequence",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, tlv(0x30, oid([2,5,29,14]) + octs(b""))))), False)
run("ext missing oid",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(octs(b"")))))), False)
run("ext missing value",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14])))))), False)
run("ext crit+value no oid",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(boolean(0xFF) + octs(b"")))))), False)
run("ext wrong order (oid,value,crit)",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + octs(b"") + boolean(0xFF)))))), False)
run("ext appended element",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + octs(b"") + integer(b"\x01")))))), False)
run("ext value wrong tag (BIT STRING)",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + bits(b"\x00"))))))), False)

# OID encodings
run("ext oid truncated",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(tlv(0x06, b"\x88") + octs(b"")))))), False)
run("ext oid nonminimal",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(tlv(0x06, b"\x2A\x80\x01") + octs(b"")))))), False)
run("ext oid empty",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(tlv(0x06, b"") + octs(b"")))))), False)

# critical encodings
for b in [0x00, 0x01, 0x7F, 0xFE]:
    run(f"critical 0x{b:02X}",
        cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + boolean(b) + octs(b"")))))), False)
run("critical empty",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + tlv(0x01, b"") + octs(b"")))))), False)
run("critical multibyte FFFF",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + tlv(0x01, b"\xFF\xFF") + octs(b"")))))), False)
run("two critical booleans",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, seq(seq(oid([2,5,29,14]) + boolean(0xFF) + boolean(0xFF) + octs(b"")))))), False)

# truncation / trailing garbage
good = ext()
run("truncated extension item",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, bytes([0x30]) + L(len(good)) + good[:-1])))), False)
run("garbage byte in extensions seq",
    cert_of(tbs_of(version=2, extra=tlv(0xA3, tlv(0x30, ext() + b"\x42"))))), False)

fails = 0
for name, ok, code, out, err in results:
    if not ok:
        fails += 1
        print(f"FAIL  {name}  (exit {code})\n   stdout={out[:80]!r}\n   stderr={err[:200]!r}")
    else:
        print(f"PASS  {name}")
print(f"\n{len(results)-fails}/{len(results)} passed")

